1	import { ClaimSchema } from "@sonar-ai/core";
2	import { z } from "zod";
3	import type { AgentDef } from "../runner/types";
4	
5	/**
6	 * A claim as the MODEL produces it — no ID. Derived from the core `Claim` schema
7	 * so it cannot drift. `finalize` assigns the stable claim ID. Shared by every
8	 * agent whose output carries evidence-linked claims.
9	 */
10	export const ClaimDraftSchema = ClaimSchema.omit({ id: true });
11	export type ClaimDraft = z.infer<typeof ClaimDraftSchema>;
12	
13	/**
14	 * A committee agent, from the agents lane's point of view.
15	 *
16	 * The model produces a **draft** (`TDraft`): semantic content only, no IDs. A
17	 * pure `finalize` turns that draft into the core output type (`TOutput`),
18	 * assigning deterministic IDs. This keeps structured output robust (the model
19	 * never invents an ID) and keeps IDs testable and stable across replays.
20	 *
21	 * The orchestrator runs `def` through an `AgentRunner`, then calls `finalize`:
22	 *
23	 *   const draft = (await runner.run(agent.def, ctx)).output;
24	 *   const output = agent.finalize(draft, ctx);   // core type, ready for the gate
25	 *
26	 * Draft schemas are DERIVED from the core output schemas (via `.omit`), so they
27	 * can never drift from the contract.
28	 */
29	export interface Agent<TContext, TDraft, TOutput> {
30	  def: AgentDef<TContext, TDraft>;
31	  finalize(draft: TDraft, context: TContext): TOutput;
32	}
