1	import {
2	  FundamentalReportSchema,
3	  type Evidence,
4	  type Instrument,
5	} from "@sonar-ai/core";
6	import { describe, expect, it } from "vitest";
7	import { StubAgentRunner } from "../runner/stub-runner";
8	import {
9	  fundamentalAnalyst,
10	  FundamentalReportDraftSchema,
11	  type FundamentalContext,
12	  type FundamentalReportDraft,
13	} from "./fundamental-analyst";
14	
15	const INSTRUMENT: Instrument = {
16	  id: "inst_nvidia",
17	  symbol: "NVDA",
18	  name: "Nvidia",
19	  sector: "Semiconductors",
20	  assetClass: "equity",
21	  currency: "EUR",
22	};
23	
24	const EVIDENCE: Evidence[] = [
25	  { id: "ev_nvda_fund", kind: "filing", title: "Nvidia data-center revenue growth", sourceName: "Synthetic filing", observedAt: "2026-08-01T00:00:00Z", label: "synthetic" },
26	  { id: "ev_nvda_supplier", kind: "cala", title: "GlobalCloud sources GPUs from Nvidia", sourceName: "Cala", observedAt: "2026-08-20T00:00:00Z", label: "synthetic" },
27	];
28	
29	const CONTEXT: FundamentalContext = {
30	  instrument: INSTRUMENT,
31	  evidence: EVIDENCE,
32	  priorThesis: null,
33	};
34	
35	const DRAFT: FundamentalReportDraft = {
36	  quality: "Dominant AI accelerator franchise with a wide software moat.",
37	  valuation: "Rich on trailing multiples; justified only if datacenter demand persists.",
38	  financialStrength: "Strong balance sheet, high gross margins.",
39	  catalysts: ["GlobalCloud capex cycle"],
40	  risks: ["Demand air-pocket if AI capex slows"],
41	  claims: [
42	    { statement: "Nvidia datacenter revenue is growing on hyperscaler capex.", stance: "bull", evidenceIds: ["ev_nvda_fund"] },
43	  ],
44	};
45	
46	describe("fundamentalAnalyst", () => {
47	  it("accepts a well-formed draft (no IDs) against its output schema", () => {
48	    expect(FundamentalReportDraftSchema.safeParse(DRAFT).success).toBe(true);
49	  });
50	
51	  it("builds a prompt that names the instrument and exposes every evidence ID", () => {
52	    const prompt = fundamentalAnalyst.def.buildInput(CONTEXT);
53	    expect(prompt).toContain("Nvidia");
54	    for (const e of EVIDENCE) expect(prompt).toContain(e.id);
55	  });
56	
57	  it("finalizes a draft into a schema-valid report with deterministic IDs", () => {
58	    const report = fundamentalAnalyst.finalize(DRAFT, CONTEXT);
59	    expect(FundamentalReportSchema.safeParse(report).success).toBe(true);
60	    expect(report.id).toBe("frp_inst_nvidia");
61	    expect(report.instrumentId).toBe("inst_nvidia");
62	    expect(report.claims[0]!.id).toBe("clm_inst_nvidia_0");
63	  });
64	
65	  it("produces claims whose evidence all resolves to the provided pack", () => {
66	    const report = fundamentalAnalyst.finalize(DRAFT, CONTEXT);
67	    const known = new Set(EVIDENCE.map((e) => e.id));
68	    const referenced = report.claims.flatMap((c) => c.evidenceIds);
69	    expect(referenced.every((id) => known.has(id))).toBe(true);
70	  });
71	
72	  it("runs end-to-end through the StubAgentRunner for one instrument", async () => {
73	    const runner = new StubAgentRunner({ fundamental_analyst: DRAFT });
74	    const { output } = await runner.run(fundamentalAnalyst.def, CONTEXT);
75	    const report = fundamentalAnalyst.finalize(output, CONTEXT);
76	    expect(FundamentalReportSchema.safeParse(report).success).toBe(true);
77	  });
78	});
