1	import type { AgentStage } from "@sonar-ai/core";
2	import type { ZodType } from "zod";
3	
4	/**
5	 * The seam between deterministic stubs and real OpenAI calls.
6	 *
7	 * Agents are DATA, runners are BEHAVIOR. Each agent is an {@link AgentDef}:
8	 * a stage id, instructions, an output schema, and a function that turns its
9	 * isolated context pack into a model input. A {@link AgentRunner} executes a
10	 * def. `StubAgentRunner` (Phase 3) returns canned fixture outputs;
11	 * `OpenAIAgentRunner` (Phase 5) calls the model — swapping one for the other is
12	 * the only change needed to go from an offline demo to live agents.
13	 */
14	
15	/** One committee agent, defined by what it must produce — never an SDK call. */
16	export interface AgentDef<TContext, TOutput> {
17	  stage: AgentStage;
18	  /** System / instruction prompt for this agent. */
19	  instructions: string;
20	  /**
21	   * Zod schema the output must satisfy. Also the source of the OpenAI
22	   * structured-output JSON schema, so the model can never return a shape the
23	   * contract does not accept.
24	   */
25	  outputSchema: ZodType<TOutput>;
26	  /** Build the model input from the isolated context pack. */
27	  buildInput(context: TContext): string;
28	}
29	
30	export interface AgentUsage {
31	  inputTokens: number;
32	  outputTokens: number;
33	}
34	
35	export interface AgentRunResult<TOutput> {
36	  output: TOutput;
37	  usage?: AgentUsage;
38	}
39	
40	/**
41	 * Executes an {@link AgentDef}. Implementations MUST validate the produced
42	 * output against `def.outputSchema` before returning, and MUST NOT leak
43	 * prompts, credentials, or hidden reasoning to their caller — only the typed
44	 * output crosses this boundary.
45	 */
46	export interface AgentRunner {
47	  run<TContext, TOutput>(
48	    def: AgentDef<TContext, TOutput>,
49	    context: TContext,
50	  ): Promise<AgentRunResult<TOutput>>;
51	}
